local mapper = mapper
local config_qos = "qos"

-- uci.wansensing
mapper("uci_1to1").registerConfigMap(config_qos)

-- uci.qos.global.
local qos_global  = {
    config = config_qos,
    section = "global",
    type = "qos",
    options = { },
}


mapper("uci_1to1").registerSimpleMap(qos_global)

-- uci.qos.interface.{i}
local qos_interface = {
  config = config_qos,
  type = "interface",
  options = { "classgroup", "enabled", }
}
mapper("uci_1to1").registerNamedMultiMap(qos_interface)